enum WaveRegion
{
  WAVE_REGIONBACK = 0,
  WAVE_REGIONFACE = 3,
  WAVE_REGIONLIP = 5,
  WAVE_REGIONTUBE = 9,
  WAVE_REGIONCHIN = 11,
  WAVE_REGIONLIP2 = 12
};

struct BeachData
{
  char pad0[0xd0];
  int bdir;
  char pad1[0x80];
  int is_small_wave;
  char pad2[0xbc];
};

extern BeachData BeachDataArray[];

class game
{
  char pad[0x228];
  int beach_id;

public:
  int get_beach_id() const { return beach_id; }
};

extern game *g_game_ptr;

class board_controller
{
  char pad[0xa64];
  int current_region;

public:
  bool InLaunchRegion(void)
  {
    return ((current_region == WAVE_REGIONLIP)
      || (current_region == WAVE_REGIONLIP2)
      || (current_region == WAVE_REGIONCHIN)
      || (current_region == WAVE_REGIONFACE)
      || (current_region == WAVE_REGIONBACK));
  }

  bool InTubeRegion(void)
  {
    return current_region == WAVE_REGIONTUBE;
  }
};

enum
{
  SURFER_ANIM_TRK_TUBE_GRAB_L_1 = 109,
  SURFER_ANIM_TRK_TUBE_GRAB_R_1 = 116
};

class kellyslater_controller
{
  char pad0[0x54];
  int stand_anim_nums[6];
  char pad1[0x174];
  bool goofy;
  char pad2[0x197];
  board_controller my_board_controller;
  char pad3[0xd08];
  int stand_num;

public:
  bool Z_Within_Tube(void);
  int StandAnim(void);
};

int kellyslater_controller::StandAnim(void)
{
	stand_num++;
	if (stand_num > 2)
		stand_num = 0;

	if (my_board_controller.InTubeRegion() && this->Z_Within_Tube())
	{
		if (BeachDataArray[g_game_ptr->get_beach_id()].is_small_wave)
		{
			//  Always grab the outside rail.
			bool left_wave = BeachDataArray[g_game_ptr->get_beach_id()].bdir;
			if ((left_wave && !goofy) || (!left_wave && goofy))  
				return SURFER_ANIM_TRK_TUBE_GRAB_L_1;
			else
				return SURFER_ANIM_TRK_TUBE_GRAB_R_1;
		}

		return (stand_anim_nums[5]);
	}
	else if (my_board_controller.InLaunchRegion())
		return (stand_anim_nums[stand_num + 3]);

	return (stand_anim_nums[stand_num]);

}
